    // ad_user
    let topics = all_host_inspection_topics(
        "Analyze the AD user administrator. Show their SID and group memberships.",
    );
    assert!(
        topics.contains(&"ad_user"),
        "should detect ad_user; got: {topics:?}"
    );

    // hyperv
