static COMPOSE_YAML: &str = "
version: \"3.8\"
services:
  api:
    image: myapp:latest
    ports:
      - \"8080:80\"
    environment:
      - DB_HOST=db
      - DB_PASSWORD=secret123
    depends_on:
      - db
    restart: unless-stopped
  db:
    image: postgres:15
    ports:
      - \"5432:5432\"
    volumes:
      - pgdata:/var/lib/postgresql/data
    environment:
      POSTGRES_PASSWORD: secret
    restart: always
  redis:
    image: redis:7
    ports:
      - \"6379:6379\"
    restart: always
volumes:
  pgdata:
networks:
  default:
    driver: bridge
";

