// ── openapi_tools ─────────────────────────────────────────────────────────────

static OPENAPI_SPEC: &str = r#"
openapi: "3.0.3"
info:
  title: Pet Store API
  version: "1.0.0"
  description: A sample API for testing
servers:
  - url: https://api.example.com/v1
    description: Production
paths:
  /pets:
    get:
      summary: List all pets
      operationId: listPets
      tags:
        - pets
      responses:
        "200":
          description: A list of pets
    post:
      summary: Create a pet
      operationId: createPet
      tags:
        - pets
      responses:
        "201":
          description: Created
  /pets/{petId}:
    get:
      summary: Get a pet by ID
      operationId: showPetById
      tags:
        - pets
      deprecated: true
      responses:
        "200":
          description: A pet
components:
  schemas:
    Pet:
      type: object
      required:
        - id
        - name
      properties:
        id:
          type: integer
        name:
          type: string
        tag:
          type: string
"#;

