const GQL_SCHEMA: &str = "
type Query {
  user(id: ID!): User
  posts: [Post!]!
}
type User {
  id: ID!
  name: String!
  email: String
  role: Role!
}
type Post {
  id: ID!
  title: String!
  author: User!
}
enum Role {
  ADMIN
  USER
  GUEST
}
interface Node {
  id: ID!
}
input CreateUserInput {
  name: String!
  email: String!
}
";

