#[tokio::test]
async fn test_base_tools_encode_all() {
    use hematite::tools::base_tools;
    let args = serde_json::json!({ "input": "hello" });
    let result = base_tools::execute(&args).await.unwrap();
    assert!(
        result.contains("encode"),
        "output should contain encode header"
    );
    assert!(result.contains("Base16"), "should show Base16");
    assert!(result.contains("Base32"), "should show Base32");
    assert!(result.contains("Base58"), "should show Base58");
    assert!(result.contains("Base85"), "should show Base85");
}

#[tokio::test]
async fn test_base_tools_encode_base32() {
    use hematite::tools::base_tools;
    let args = serde_json::json!({ "input": "hello", "encoding": "base32" });
    let result = base_tools::execute(&args).await.unwrap();
    // base32("hello") = NBSWY3DPEB3W64TMMQ (without padding)
    assert!(
        result.contains("NBSWY") || result.contains("Base32"),
        "base32 encode should include NBSWY prefix: {}",
        result
    );
}

#[tokio::test]
async fn test_base_tools_decode_base32_roundtrip() {
    use hematite::tools::base_tools;
    let encode_args = serde_json::json!({ "input": "roundtrip", "encoding": "base32" });
    let encoded = base_tools::execute(&encode_args).await.unwrap();
    // Extract the encoded value from output
    let encoded_val = encoded
        .lines()
        .find(|l| l.contains("Base32:"))
        .and_then(|l| l.split(':').nth(1))
        .map(|s| s.trim().to_string())
        .unwrap_or_default();

    let decode_args = serde_json::json!({
        "action": "decode",
        "input": encoded_val,
        "encoding": "base32"
    });
    let decoded = base_tools::execute(&decode_args).await.unwrap();
    assert!(
        decoded.contains("roundtrip"),
        "decode should recover original: {}",
        decoded
    );
}

#[tokio::test]
async fn test_base_tools_decode_base58() {
    use hematite::tools::base_tools;
    // Encode then decode
    let enc = serde_json::json!({ "input": "test123", "encoding": "base58" });
    let encoded = base_tools::execute(&enc).await.unwrap();
    let encoded_val = encoded
        .lines()
        .find(|l| l.contains("Base58:"))
        .and_then(|l| l.split(':').nth(1))
        .map(|s| s.trim().to_string())
        .unwrap_or_default();

    let dec = serde_json::json!({
        "action": "decode",
        "input": encoded_val,
        "encoding": "base58"
    });
    let decoded = base_tools::execute(&dec).await.unwrap();
    assert!(
        decoded.contains("test123"),
        "base58 roundtrip should recover original: {}",
        decoded
    );
}

